-- READ ONLY. Select project dkhwwvoplhfjccvjegty before running in SQL Editor.
-- No Auth secrets, account passwords, tokens, or ordinary-user data selected.
select jsonb_build_object(
 'checked_at',now(),'database',current_database(),'postgres',current_setting('server_version'),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname='public' and c.relname in ('legal_documents','legal_revisions','legal_events','user_roles','profiles')) or (n.nspname='auth' and c.relname in ('users','sessions'))),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) order by n.nspname,c.relname,a.attnum),'[]'::jsonb) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where a.attnum>0 and not a.attisdropped and ((n.nspname='public' and c.relname in ('legal_documents','legal_revisions','legal_events','user_roles')) or (n.nspname='auth' and ((c.relname='users' and a.attname='id') or (c.relname='sessions' and a.attname in ('id','user_id','not_after')))))),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) order by n.nspname,c.relname,k.conname),'[]'::jsonb) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth') and c.relname in ('legal_documents','legal_revisions','legal_events','user_roles','users')),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'definition',pg_get_functiondef(p.oid)) order by n.nspname,p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='unseen_private' and p.proname in ('is_admin','valid_legal_text','valid_legal_content','guard_legal_write','change_legal_document')) or (n.nspname='public' and p.proname in ('admin_cms_status','admin_legal_state','admin_save_legal_draft','admin_publish_legal','admin_revoke_legal','admin_restore_legal')) or (n.nspname='auth' and p.proname='uid')),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname),'[]'::jsonb) from pg_policies p where schemaname='public' and tablename in ('user_roles','legal_documents','legal_revisions','legal_events')),
 'schema_permissions',(select jsonb_build_object('exists',true,'owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl,'authenticated_usage',has_schema_privilege('authenticated',n.oid,'USAGE'),'anon_usage',has_schema_privilege('anon',n.oid,'USAGE')) from pg_namespace n where n.nspname='unseen_private'),
 'admin_permission_dependencies',jsonb_build_object('authenticated_is_admin_execute',has_function_privilege('authenticated','unseen_private.is_admin()','EXECUTE'),'authenticated_status_execute',has_function_privilege('authenticated','public.admin_cms_status()','EXECUTE'),'uuid_generator',to_regprocedure('gen_random_uuid()')::text),
 'admins',(select jsonb_build_object('count',count(*),'identities_present',count(u.id),'identity_fingerprints',jsonb_agg(md5(r.user_id::text) order by md5(r.user_id::text))) from public.user_roles r left join auth.users u on u.id=r.user_id where r.role='admin'),
 'destination_inventory',(select jsonb_build_object('count',count(*),'statuses',(select jsonb_object_agg(status,n) from (select status,count(*) n from public.places group by status) s),'id_slug_status_fingerprint',md5(coalesce(string_agg(id::text||':'||slug||':'||status::text,'|' order by id),''))) from public.places),
 'migration_history',(select coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) order by version),'[]'::jsonb) from supabase_migrations.schema_migrations)
) as legal_activation_preflight;
